import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';
import * as serviceWorkerRegistration from './serviceWorkerRegistration'; // ใช้ไฟล์นี้สำหรับ PWA
import './index.css'; // ถ้ามี CSS รวม

ReactDOM.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
  document.getElementById('root')
);

// ✅ ลงทะเบียน Service Worker เพื่อให้เว็บทำงาน offline และเป็น PWA
serviceWorkerRegistration.register();
